        customer: "John Doe",
        amount: 99.99
    }),
    MessageAttributes: {
        "event_type": {
            DataType: "String",
            StringValue: "order_created"
        },
        "severity": {
            DataType: "String",
            StringValue: "INFO"
        },
        "environment": {
            DataType: "String",
            StringValue: "production"
        },
        "is_priority": {
            DataType: "String",
            StringValue: "false"
        },
        "order_amount": {
            DataType: "Number",
            StringValue: "99.99"
        },
        "timestamp": {
            DataType: "String",
            StringValue: new Date().toISOString()
        }
    }
};

await sns.send(new PublishCommand(params));

// Subscriber-side (Lambda)
exports.handler = async (event) => {
    for (const record of event.Records) {
        const sns = record.Sns;
        const attributes = sns.MessageAttributes;

        // Access message attributes
        const eventType = attributes.event_type.Value;
        const severity = attributes.severity.Value;
        const isPriority = attributes.is_priority.Value === 'true';

        console.log(`Event Type: ${eventType}`);
        console.log(`Severity: ${severity}`);

        // Process based on attributes
        if (isPriority) {
            await processPriorityMessage(JSON.parse(sns.Message));
        } else {
            await processRegularMessage(JSON.parse(sns.Message));
        }
    }
};
